SELECT 
    TRY_CAST(TRIM(FiscalYear) AS INT) AS FiscalYear, 
    AgencyName, 
    TRY_CAST(TotalPaid AS FLOAT) AS TotalPaid
FROM [dbo].[NYC_Payroll_Summary];

SELECT DISTINCT FiscalYear 
FROM [dbo].[NYC_Payroll_Summary] 
WHERE TRY_CAST(FiscalYear AS INT) IS NULL;

SELECT DISTINCT FiscalYear 
FROM [dbo].[NYC_Payroll_Summary];

SELECT DISTINCT AgencyName 
FROM [dbo].[NYC_Payroll_Summary];

SELECT DISTINCT TotalPaid
FROM [dbo].[NYC_Payroll_Summary];
